def transform(grid):
    h,w=len(grid),len(grid[0])
    known={}
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v: known[(c-r)%7]=v
    # Fill period-7 diagonal stripes, extrapolating the color cycle.
    seq={0:6,1:9,2:8}
    for k,v in known.items(): seq[k]=v
    # observed clue of 5 is on index 5 mod 7; extend remaining palette by cycle.
    if 5 not in seq: seq[5]=5
    if 3 not in seq: seq[3]=7
    if 4 not in seq: seq[4]=3
    return [[seq[(c-r)%7] for c in range(w)] for r in range(h)]
