def transform(grid):
    h,w=len(grid),len(grid[0])
    # Classify each diagonal by its offset; the clue tracks define a repeating
    # diagonal color pattern across the canvas.
    # Period 14 is established by repeated 5 track separated from the 9 track.
    period=14
    known={}
    for r in range(h):
        for c in range(w):
            v=grid[r][c]
            if v: known[(c-r)%period]=v
    out=[[0]*w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            out[r][c]=known.get((c-r)%period,0)
    return out
